// ✗ 타입만
expect(typeof total(items)).toBe('number');

// ✗ 참거짓만
expect(total(items)).toBeTruthy();

// ✗ 기대값을 같은 계산으로 만든다 (가장 흔하다)
expect(total(items)).toBe(items.reduce((s, i) => s + i.price * i.n, 0));

// ✗ 확인이 없다 — 준비만 하고 끝
const r = total(items);

// ✓ 손으로 적은 기대값
expect(total([{ price: 100, n: 3 }])).toBe(300);

// ② 먼저 (빨강)
it('10% 할인은 900', () => {
  expect(discount(1000, 10)).toBe(900);
});
// → ReferenceError: discount is not defined  ← 이 빨강을 본다

// ④ 그다음 (초록)
function discount(price, pct) {
  return Math.round(price * (100 - pct) / 100);
}

// ⑤ 정리 — 초록을 유지한 채

// 아직 slug() 는 없다. 무엇을 약속할지부터 적는다.
it('공백을 하이픈으로', () => expect(slug('Hello World')).toBe('hello-world'));
it('빈 문자열은 빈 값', () => expect(slug('')).toBe(''));
it('40자에서 자른다', () => expect(slug('a'.repeat(60))).toHaveLength(40));
it('문자열이 아니면 던진다', () => expect(() => slug(123)).toThrow());

// ← 이 네 줄이 이미 설계 문서다. 구현은 이걸 만족시키면 된다.

const cases = [
  ['빈 목록', [], 0],
  ['한 항목', [{ price: 100, n: 2 }], 200],
  ['두 항목', [{ price: 100, n: 2 }, { price: 50, n: 1 }], 250],
];

for (const [name, input, want] of cases) {
  it(`합계 — ${name}`, () => {
    expect(total(input)).toBe(want);      // 실패 시 어느 경우인지 이름에 있다
  });
}

// ✗ 반대로: 한 테스트 안에서 10가지를 돌면
//   첫 실패에서 멈춰 나머지는 확인도 못 하고, 어느 경우인지도 흐릿하다

// 「맞는 동작」이 아니라 「지금 이런다」의 기록
it('현재 동작: 빈 입력이면 빈 배열', () => {
  expect(legacyParse('')).toEqual([]);
});
it('현재 동작: 공백만이면 빈 문자열 하나가 남는다 (의도인지는 모름)', () => {
  expect(legacyParse(' ')).toEqual(['']);
});

